import { z } from 'zod'

export const dietPlanFormSchema = z.object({
  plan_id: z.union([z.number(), z.string()]).transform((v) => Number(v)),
  day_number: z
    .union([z.number(), z.string()])
    .transform((v) => Number(v))
    .refine((v) => Number.isFinite(v) && v >= 1, 'Day number must be >= 1'),
  sequence_number: z
    .union([z.number(), z.string()])
    .transform((v) => Number(v))
    .refine(
      (v) => Number.isFinite(v) && v >= 1,
      'Sequence number must be >= 1'
    ),
  meal_time: z.string().min(1, 'Meal time is required'),
  meal_name: z.string().optional().or(z.literal('')),
  protein: z
    .union([z.number(), z.string()])
    .transform((v) =>
      v === '' || v === null || v === undefined ? '' : Number(v)
    )
    .optional()
    .or(z.literal('')),
  carbs: z
    .union([z.number(), z.string()])
    .transform((v) =>
      v === '' || v === null || v === undefined ? '' : Number(v)
    )
    .optional()
    .or(z.literal('')),
  fat: z
    .union([z.number(), z.string()])
    .transform((v) =>
      v === '' || v === null || v === undefined ? '' : Number(v)
    )
    .optional()
    .or(z.literal('')),
  fiber: z
    .union([z.number(), z.string()])
    .transform((v) =>
      v === '' || v === null || v === undefined ? '' : Number(v)
    )
    .optional()
    .or(z.literal('')),
  total_calories: z
    .union([z.number(), z.string()])
    .transform((v) =>
      v === '' || v === null || v === undefined ? '' : Number(v)
    )
    .optional()
    .or(z.literal('')),
  calories: z
    .union([z.number(), z.string()])
    .transform((v) =>
      v === '' || v === null || v === undefined ? '' : Number(v)
    )
    .optional()
    .or(z.literal('')),
  meals: z
    .array(
      z.object({
        meal_id: z
          .union([z.number(), z.string()])
          .transform((v) => Number(v))
          .refine((v) => Number.isFinite(v) && v > 0, 'Meal name is required'),
        count: z
          .union([z.number(), z.string()])
          .transform((v) => Number(v))
          .refine(
            (v) => Number.isFinite(v) && v >= 1,
            'Intake quantity must be at least 1'
          ),
        // New field: key requirement toggle per meal
        requirement: z.enum(['Optional', 'Mandatory']).default('Optional'),
        protein: z
          .union([z.number(), z.string()])
          .transform((v) =>
            v === '' || v === null || v === undefined ? '' : Number(v)
          )
          .optional()
          .or(z.literal('')),
        carbs: z
          .union([z.number(), z.string()])
          .transform((v) =>
            v === '' || v === null || v === undefined ? '' : Number(v)
          )
          .optional()
          .or(z.literal('')),
        fat: z
          .union([z.number(), z.string()])
          .transform((v) =>
            v === '' || v === null || v === undefined ? '' : Number(v)
          )
          .optional()
          .or(z.literal('')),
        fiber: z
          .union([z.number(), z.string()])
          .transform((v) =>
            v === '' || v === null || v === undefined ? '' : Number(v)
          )
          .optional()
          .or(z.literal('')),
        total_calories: z
          .union([z.number(), z.string()])
          .transform((v) =>
            v === '' || v === null || v === undefined ? '' : Number(v)
          )
          .optional()
          .or(z.literal('')),
      })
    )
    .optional()
    .default([]),
})

export type DietPlanSchema = z.infer<typeof dietPlanFormSchema>
